INSERT INTO notification_channel (code, name_en, names, address_format, description_en, descriptions, sort) VALUES ('LINE', 'LINE', '{"th":"ไลน์","en":"LINE"}', 'LINE personal ID or LINE Official Account user ID', 'Dominant messaging channel in Thailand (90%+ penetration). Highest engagement.', '{"th":"ช่องทางรับส่งข้อความหลักในประเทศไทย มีการใช้งานมากกว่า 90 เปอร์เซ็นต์และมีการมีส่วนร่วมสูงสุด","en":"Dominant messaging channel in Thailand (90%+ penetration). Highest engagement."}', 1) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, address_format = excluded.address_format, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;
INSERT INTO notification_channel (code, name_en, names, address_format, description_en, descriptions, sort) VALUES ('EMAIL', 'Email', '{"th":"อีเมล","en":"Email"}', 'RFC 5322 email address', 'Universal but lower engagement in Thailand. Good for digests and receipts.', '{"th":"ใช้ได้ทั่วไปแต่มีการมีส่วนร่วมในไทยต่ำกว่า เหมาะสำหรับสรุปข้อมูลและใบเสร็จ","en":"Universal but lower engagement in Thailand. Good for digests and receipts."}', 2) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, address_format = excluded.address_format, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;
INSERT INTO notification_channel (code, name_en, names, address_format, description_en, descriptions, sort) VALUES ('SMS', 'SMS', '{"th":"เอสเอ็มเอส","en":"SMS"}', 'E.164 phone number', 'Reliable delivery; cost per message. Good for OTP and critical alerts.', '{"th":"ส่งถึงผู้รับได้อย่างน่าเชื่อถือ แต่มีค่าใช้จ่ายต่อข้อความ เหมาะสำหรับรหัส OTP และการแจ้งเตือนสำคัญ","en":"Reliable delivery; cost per message. Good for OTP and critical alerts."}', 3) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, address_format = excluded.address_format, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;
INSERT INTO notification_channel (code, name_en, names, address_format, description_en, descriptions, sort) VALUES ('PUSH', 'Push', '{"th":"การแจ้งเตือนแบบ Push","en":"Push"}', 'Web Push subscription token (PWA)', 'Requires PWA installation. Free at scale; limited reach until adoption grows.', '{"th":"ต้องติดตั้ง PWA ไม่มีค่าใช้จ่ายเมื่อใช้งานในปริมาณมาก แต่การเข้าถึงยังจำกัดจนกว่าจะมีผู้ติดตั้งเพิ่ม","en":"Requires PWA installation. Free at scale; limited reach until adoption grows."}', 4) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, address_format = excluded.address_format, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;
INSERT INTO notification_channel (code, name_en, names, address_format, description_en, descriptions, sort) VALUES ('IN_APP', 'In-app', '{"th":"การแจ้งเตือนในแอป","en":"In-app"}', 'Internal user ID (delivered when user opens app/site)', 'Always works for signed-in users; only seen when user is active.', '{"th":"ใช้งานได้เสมอสำหรับผู้ที่ลงชื่อเข้าใช้ แต่จะแสดงเมื่อผู้ใช้กำลังใช้งานแอปหรือเว็บไซต์","en":"Always works for signed-in users; only seen when user is active."}', 5) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, address_format = excluded.address_format, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;
